import React, { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { API_URL, apiGet, apiPost } from "./api";
import { executeChatCommand } from "./chatCommands";
import {
  addCartItem,
  fetchUserCart,
  subscribeToTravelDataChanges,
} from "./userTravelStore";

const FALLBACK_IMAGE = "/no-image.png";
const FAILED_CHAT_IMAGES = new Set();

function resolveImageSrc(image) {
  if (!image) return FALLBACK_IMAGE;
  if (typeof image === "string" && image.startsWith("http")) return image;
  if (typeof image === "string" && image.startsWith("/uploads/")) return `${API_URL}${image}`;
  return `${API_URL}/uploads/${image}`;
}

function getPlaceQueue(place) {
  const all = [place?.image, ...(place?.images || [])].filter(Boolean);
  return Array.from(new Set(all.map((img) => resolveImageSrc(img))));
}

function getChatPlaceImage(place) {
  const next = getPlaceQueue(place).find((url) => !FAILED_CHAT_IMAGES.has(url));
  return next || FALLBACK_IMAGE;
}

export default function AIChatPage() {
  const navigate = useNavigate();
  const [language, setLanguage] = useState("en");
  const [destination, setDestination] = useState("");
  const [message, setMessage] = useState("");
  const [reply, setReply] = useState("");
  const [chatHistory, setChatHistory] = useState([]);
  const [responseSource, setResponseSource] = useState("");
  const [llmError, setLlmError] = useState("");
  const [loading, setLoading] = useState(false);
  const [coords, setCoords] = useState(null);
  const [approvedPlaces, setApprovedPlaces] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    if (!navigator.geolocation) return;
    navigator.geolocation.getCurrentPosition(
      (pos) => setCoords({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
      () => setCoords(null)
    );
  }, []);

  useEffect(() => {
    apiGet("/get-approved-places")
      .then((items) => setApprovedPlaces(Array.isArray(items) ? items : []))
      .catch(() => setApprovedPlaces([]));
  }, []);

  useEffect(() => {
    let alive = true;
    const loadCart = async () => {
      try {
        const items = await fetchUserCart();
        if (alive) setCart(items);
      } catch {
        if (alive) setCart([]);
      }
    };

    void loadCart();
    const unsubscribe = subscribeToTravelDataChanges(() => {
      void loadCart();
    }, { types: ["cart"] });

    return () => {
      alive = false;
      unsubscribe();
    };
  }, []);

  const generatedPlaces = useMemo(() => {
    const text = (reply || "").toLowerCase();
    if (!text) return [];
    return approvedPlaces
      .filter((p) => {
        const name = (p.placeName || "").trim().toLowerCase();
        return name.length > 2 && text.includes(name);
      })
      .slice(0, 6);
  }, [reply, approvedPlaces]);

  const isInCart = (place) =>
    cart.some((c) => c._id === place._id || c.placeName === place.placeName);

  const addToCart = async (place) => {
    if (isInCart(place)) return;
    try {
      const next = await addCartItem({
        _id: place._id,
        placeName: place.placeName,
        image: place.image,
      });
      setCart(next);
    } catch (err) {
      alert(err.message || "Failed to add place.");
    }
  };

  const addToItinerary = async (place) => {
    await addToCart(place);
    navigate("/ai-itinerary");
  };

  async function handleChat() {
    const userText = message.trim();
    if (!userText) return;
    const cmd = executeChatCommand(userText);
    if (cmd.handled) {
      const assistantText = cmd.message ? (cmd.message.startsWith("Pathease Assistant:") ? cmd.message : `Pathease Assistant: ${cmd.message}`) : "Pathease Assistant: Done.";
      setReply(assistantText);
      setChatHistory((prev) => [
        ...prev,
        { role: "user", text: userText },
        { role: "assistant", text: assistantText },
      ]);
      setResponseSource("local-command");
      setLlmError("");
      setMessage("");
      return;
    }
    setLoading(true);
    setReply("");
    setResponseSource("");
    setLlmError("");
    try {
      const data = await apiPost("/ai/guide-chat", {
        message: userText,
        destination,
        language,
        lat: coords?.lat,
        lng: coords?.lng,
        history: chatHistory,
      });
      const r = data.reply || data.error || "";
      const assistantText = r ? (r.startsWith("Pathease Assistant:") ? r : `Pathease Assistant: ${r}`) : "";
      setReply(assistantText);
      setChatHistory((prev) => [
        ...prev,
        { role: "user", text: userText },
        { role: "assistant", text: assistantText },
      ]);
      setResponseSource(data.source || "");
      setLlmError(data.llm_error || "");
    } catch (err) {
      setReply(err?.message || "Failed to reach the guide service.");
      setChatHistory((prev) => [
        ...prev,
        { role: "user", text: userText },
        { role: "assistant", text: err?.message || "Failed to reach the guide service." },
      ]);
      setResponseSource("request-error");
      setLlmError(err?.message || "Request failed");
    } finally {
      setLoading(false);
      setMessage("");
    }
  }

  function speakText(text) {
    if (!text) return;
    if (!window.speechSynthesis) {
      alert("Speech Synthesis not supported in this browser.");
      return;
    }
    const out = /^pathease assistant:/i.test(text) ? text : `Pathease Assistant: ${text}`;
    const utterance = new SpeechSynthesisUtterance(out);
    utterance.lang = language === "hi" ? "hi-IN" : language === "mr" ? "mr-IN" : "en-IN";
    window.speechSynthesis.speak(utterance);
  }

  return (
    <div style={{ padding: 20, maxWidth: 900, margin: "0 auto" }}>
      <h1>AI Tourist Chat</h1>

      <div style={{ marginBottom: 12 }}>
        <label style={{ fontWeight: 600, marginRight: 8 }}>Language</label>
        <select
          value={language}
          onChange={(e) => setLanguage(e.target.value)}
          style={{ padding: 6, borderRadius: 6, border: "1px solid #ccc" }}
        >
          <option value="en">English</option>
          <option value="hi">Hindi</option>
          <option value="mr">Marathi</option>
        </select>
      </div>

      <input
        value={destination}
        onChange={(e) => setDestination(e.target.value)}
        placeholder="Destination (optional)"
        style={{ width: "100%", padding: 8, borderRadius: 6, border: "1px solid #ccc", marginBottom: 10 }}
      />

      <textarea
        rows={4}
        value={message}
        onChange={(e) => setMessage(e.target.value)}
        placeholder="Ask your travel question..."
        style={{ width: "100%", padding: 8, borderRadius: 6, border: "1px solid #ccc" }}
      />

      <button
        onClick={handleChat}
        style={{
          marginTop: 10,
          padding: "8px 14px",
          borderRadius: 8,
          border: "2px solid #360146ff",
          background: "#fff",
          cursor: "pointer",
          fontWeight: 600,
        }}
      >
        {loading ? "Asking..." : "Ask Guide"}
      </button>

      {reply && (
        <div style={{ marginTop: 14 }}>
          {responseSource && (
            <div
              style={{
                marginBottom: 8,
                padding: "8px 10px",
                borderRadius: 8,
                background: responseSource === "llm" ? "#e7f7ee" : "#fff4e5",
                border: `1px solid ${responseSource === "llm" ? "#9ad4af" : "#f2c27b"}`,
                fontSize: 13,
              }}
            >
              Response source: <strong>{responseSource === "llm" ? "AI model" : responseSource}</strong>
              {llmError ? ` | LLM error: ${llmError}` : ""}
            </div>
          )}
          <div style={{ background: "#f9f9f9", padding: 10, borderRadius: 8, whiteSpace: "pre-wrap", maxHeight: 320, overflowY: "auto" }}>{reply}</div>
          <button
            onClick={() => speakText(reply)}
            style={{
              marginTop: 8,
              padding: "6px 10px",
              borderRadius: 8,
              border: "1px solid #360146ff",
              background: "#fff",
              cursor: "pointer",
            }}
          >
            Speak Response
          </button>

          {generatedPlaces.length > 0 && (
            <div style={{ marginTop: 12 }}>
              <div style={{ fontWeight: 700, marginBottom: 8 }}>Places Found</div>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 10 }}>
                {generatedPlaces.map((p) => (
                  <div key={p._id || p.placeName} style={{ border: "1px solid #ddd", borderRadius: 10, padding: 8, background: "#fff" }}>
                    <img
                      src={getChatPlaceImage(p)}
                      alt={p.placeName}
                      style={{ width: "100%", height: 120, objectFit: "cover", borderRadius: 8 }}
                      onError={(e) => {
                        e.currentTarget.onerror = null;
                        FAILED_CHAT_IMAGES.add(e.currentTarget.src);
                        e.currentTarget.src = getChatPlaceImage(p);
                      }}
                    />
                    <div style={{ marginTop: 6, fontWeight: 600 }}>{p.placeName}</div>
                    <div style={{ marginTop: 8, display: "flex", gap: 8 }}>
                      <button onClick={() => addToItinerary(p)} style={{ flex: 1, padding: "6px 8px" }}>
                        Add to Itinerary
                      </button>
                      <button onClick={() => addToCart(p)} style={{ flex: 1, padding: "6px 8px" }}>
                        {isInCart(p) ? "Added" : "Add to Cart"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
