// SnapMapScreen.js — Image pins + sliding sidebar + reverse geocode
import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { MapContainer, TileLayer, Marker, Popup, useMap } from "react-leaflet";
import L from "leaflet";
import "leaflet/dist/leaflet.css";
import { API_URL, apiGet } from "./api";
import { useAuth } from "./AuthContext";
import SearchBar from "./SearchBar";
import {
  addCartItem,
  fetchUserCart,
  removeCartItem,
  subscribeToTravelDataChanges,
} from "./userTravelStore";

/* ---------------- FIX LEAFLET ICON BUG ---------------- */
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl:
    "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png",
  iconUrl:
    "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png",
  shadowUrl:
    "https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png",
});

/* ---------------- HELPERS ---------------- */
function normalizeLocation(loc) {
  if (!loc) return null;
  if (typeof loc === "object" && loc.lat && loc.lng) {
    return { lat: Number(loc.lat), lng: Number(loc.lng) };
  }
  return null;
}

function resolveImageSrc(image) {
  if (!image) return "/no-image.png";
  if (typeof image === "string" && image.startsWith("http")) return image;
  if (typeof image === "string" && image.startsWith("/uploads/")) return `${API_URL}${image}`;
  return `${API_URL}/uploads/${image}`;
}

function getImageQueue(place) {
  const raw = [place?.image, ...(place?.images || [])].filter(Boolean);
  const resolved = raw.map((img) => resolveImageSrc(img));
  return Array.from(new Set(resolved));
}

function getPreferredImage(place) {
  const queue = getImageQueue(place);
  return queue.length > 0 ? queue[0] : "/no-image.png";
}

function normalizeVoicePlaceText(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeVoiceTokens(value) {
  return normalizeVoicePlaceText(value)
    .split(" ")
    .map((t) => {
      if (t.length > 3 && t.endsWith("s")) return t.slice(0, -1);
      return t;
    })
    .filter(Boolean);
}

function findPlaceByVoiceName(list, rawName) {
  const spoken = normalizeVoicePlaceText(rawName);
  if (!spoken) return null;
  const spokenTokens = normalizeVoiceTokens(rawName).filter((t) => t.length > 2);
  let best = null;
  let bestScore = -1;
  list.forEach((place) => {
    const name = normalizeVoicePlaceText(place?.placeName);
    const nameTokens = normalizeVoiceTokens(place?.placeName);
    const tokenBag = new Set(nameTokens);
    if (!name) return;
    if (name.includes(spoken) || spoken.includes(name)) {
      if (bestScore < 100) {
        best = place;
        bestScore = 100;
      }
      return;
    }
    if (spokenTokens.length === 0) return;
    const score = spokenTokens.reduce((acc, token) => (tokenBag.has(token) || name.includes(token) ? acc + 1 : acc), 0);
    if (score > bestScore) {
      best = place;
      bestScore = score;
    }
  });
  if (bestScore <= 0) return null;
  return best;
}

function haversineKm(a, b, c, d) {
  const toRad = (x) => (x * Math.PI) / 180;
  const R = 6371;
  const dLat = toRad(c - a);
  const dLon = toRad(d - b);
  const s =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(a)) *
      Math.cos(toRad(c)) *
      Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(s), Math.sqrt(1 - s));
}

/* ---------------- MAP RECENTER ---------------- */
function Recenter({ center }) {
  const map = useMap();
  useEffect(() => {
    if (center) map.setView(center, 15, { animate: true });
  }, [center, map]);
  return null;
}

/* ---------------- IMAGE MARKER ---------------- */
function getMarkerIcon(imageQueue) {
  const queue = Array.isArray(imageQueue) && imageQueue.length > 0 ? imageQueue : ["/no-image.png"];
  const src = queue[0];
  const encodedQueue = queue.join("|");

  return L.divIcon({
    className: "",
    html: `
      <div style="
        width:46px;
        height:46px;
        border-radius:50%;
        overflow:hidden;
        border:3px solid #2196f3;
        box-shadow:0 2px 6px rgba(0,0,0,.45);
        background:white;
      ">
        <img
          src="${src}"
          data-queue="${encodedQueue}"
          data-idx="0"
          style="width:100%;height:100%;object-fit:cover;"
          onerror="
            var q = (this.dataset.queue || '').split('|');
            var i = parseInt(this.dataset.idx || '0', 10) + 1;
            if (i < q.length) { this.dataset.idx = String(i); this.src = q[i]; return; }
            this.onerror = null;
            this.src='/no-image.png';
          "
        />
      </div>
    `,
    iconSize: [46, 46],
    iconAnchor: [23, 46],
    popupAnchor: [0, -38],
  });
}

/* ---------------- USER LOCATION ICON ---------------- */
const userIcon = L.divIcon({
  className: "",
  html: `
    <div style="
      width:18px;
      height:18px;
      background:#4285f4;
      border-radius:50%;
      border:3px solid white;
      box-shadow:0 0 6px rgba(0,0,0,.5);
    "></div>
  `,
  iconSize: [18, 18],
});

/* ===================================================== */

export default function SnapMapScreen() {
  const { isLoggedIn } = useAuth();
  const [places, setPlaces] = useState([]);
  const [selected, setSelected] = useState(null);
  const [userLocation, setUserLocation] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [cart, setCart] = useState([]);
  const reverseCache = useRef(new Map());

  /* ---------------- LOAD PLACES ---------------- */
  useEffect(() => {
    (async () => {
            const data = await apiGet("/get-approved-places");
      setPlaces(
        data.map((p) => ({
          ...p,
          location: normalizeLocation(p.location),
          imageQueue: getImageQueue(p),
          image: getPreferredImage(p),
        }))
      );
    })();
  }, []);

  useEffect(() => {
    if (!isLoggedIn) {
      setCart([]);
      return;
    }
    let alive = true;
    const loadCart = async () => {
      try {
        const items = await fetchUserCart();
        if (alive) setCart(items);
      } catch {
        if (alive) setCart([]);
      }
    };

    void loadCart();
    const unsubscribe = subscribeToTravelDataChanges(() => {
      void loadCart();
    }, { types: ["cart"] });

    return () => {
      alive = false;
      unsubscribe();
    };
  }, [isLoggedIn]);

  /* ---------------- USER LOCATION ---------------- */
  useEffect(() => {
    navigator.geolocation.getCurrentPosition(
      (pos) =>
        setUserLocation({
          lat: pos.coords.latitude,
          lng: pos.coords.longitude,
        }),
      () => console.warn("Location denied")
    );
  }, []);

  /* ---------------- REVERSE GEOCODE ---------------- */
  const reverseGeocode = useCallback(async (lat, lng) => {
    const key = `${lat},${lng}`;
    if (reverseCache.current.has(key))
      return reverseCache.current.get(key);

    const res = await fetch(
      `https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lng}`
    );
    const json = await res.json();
    const name = json?.display_name || "Unknown location";
    reverseCache.current.set(key, name);
    return name;
  }, []);

  /* ---------------- OPEN SIDEBAR ---------------- */
  const openSidebar = useCallback(async (place) => {
    setSidebarOpen(true);

    let distance = null;
    if (userLocation && place.location) {
      distance =
        Math.round(
          haversineKm(
            userLocation.lat,
            userLocation.lng,
            place.location.lat,
            place.location.lng
          ) * 100
        ) / 100;
    }

    const displayName = await reverseGeocode(
      place.location.lat,
      place.location.lng
    );

    setSelected({
      ...place,
      distanceFromUser: distance,
      displayName,
    });
  }, [reverseGeocode, userLocation]);

  const isInCart = useCallback(
    (place) => cart.some((c) => c._id === place._id || c.placeName === place.placeName),
    [cart]
  );

  const addToCart = useCallback(async (place) => {
    if (!isLoggedIn) {
      alert("Please login to add to itinerary.");
      return;
    }
    if (isInCart(place)) return;
    try {
      const next = await addCartItem({
        _id: place._id,
        placeName: place.placeName,
        image: place.image,
        distance: place.distanceFromUser,
      });
      setCart(next);
    } catch (err) {
      alert(err.message || "Failed to add place.");
    }
  }, [isInCart, isLoggedIn]);

  const removeFromCart = useCallback(async (place) => {
    try {
      const next = await removeCartItem(place);
      setCart(next);
    } catch (err) {
      alert(err.message || "Failed to remove place.");
    }
  }, []);

  useEffect(() => {
    const onVoice = (e) => {
      const detail = e?.detail || {};
      if (!detail.type) return;
      if (detail.type === "open-place") {
        const name = detail.name || "";
        if (!name) return;
        const match = findPlaceByVoiceName(places, name);
        if (match) openSidebar(match);
        return;
      }
      if (detail.type === "add-to-cart") {
        if (selected) {
          void addToCart(selected);
          return;
        }
        const name = detail.name || "";
        if (!name) return;
        const match = findPlaceByVoiceName(places, name);
        if (match) void addToCart(match);
        return;
      }
      if (detail.type === "remove-from-cart") {
        if (selected) {
          void removeFromCart(selected);
          return;
        }
        const name = detail.name || "";
        if (!name) return;
        const match = findPlaceByVoiceName(places, name);
        if (match) void removeFromCart(match);
        return;
      }
      if (detail.type === "close-place") {
        setSidebarOpen(false);
      }
    };
    window.addEventListener("pathease:voice-command", onVoice);
    return () => window.removeEventListener("pathease:voice-command", onVoice);
  }, [addToCart, openSidebar, places, removeFromCart, selected]);

  /* ---------------- MAP CENTER ---------------- */
  const mapCenter = useMemo(() => {
    if (selected?.location)
      return [selected.location.lat, selected.location.lng];
    if (userLocation)
      return [userLocation.lat, userLocation.lng];
    return [20.59, 78.96];
  }, [selected, userLocation]);

  /* ===================================================== */
  return (
    <div className="snapmap-root" style={{ display: "flex", height: "100vh" }}>
      <style>{`
        .snapmap-root .leaflet-top.leaflet-left {
          top: 59px;
        }
      `}</style>
      {/* ---------------- MAP ---------------- */}
      <div style={{ flex: 1, position: "relative" }}>
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            zIndex: 1000,
            padding: 8,
            display: "flex",
            alignItems: "center",
            gap: 8,
            background: "rgba(255,255,255,0.85)",
            borderBottom: "1px solid #ddd",
          }}
        >
          <div style={{ flex: 1 }}>
            <SearchBar
              data={places}
              onSelect={(p) => openSidebar(p)}
              onSearch={(q) => {
                const match = places.find((p) =>
                  (p.placeName || "").toLowerCase().includes((q || "").toLowerCase())
                );
                if (match) openSidebar(match);
              }}
            />
          </div>
          <button
            onClick={() => setSelected(null)}
            style={{
              padding: "8px 10px",
              borderRadius: 8,
              border: "2px solid #360146ff",
              background: "#fff",
              cursor: "pointer",
              fontWeight: 700,
              whiteSpace: "nowrap",
            }}
          >
            Locate Me
          </button>
        </div>
        <MapContainer
          className="snapmap-map"
          center={mapCenter}
          zoom={14}
          style={{ width: "100%", height: "100%" }}
        >
          <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
          <Recenter center={mapCenter} />

          {/* User Marker */}
          {userLocation && (
            <Marker
              position={[userLocation.lat, userLocation.lng]}
              icon={userIcon}
            >
              <Popup>You are here</Popup>
            </Marker>
          )}

          {/* Place Markers with Images */}
          {places.map(
            (p) =>
              p.location && (
                <Marker
                  key={p._id}
                  position={[p.location.lat, p.location.lng]}
                  icon={getMarkerIcon(p.imageQueue)}
                  eventHandlers={{
                    click: () => openSidebar(p),
                  }}
                >
                  <Popup>
                    <b>{p.placeName}</b>
                  </Popup>
                </Marker>
              )
          )}
        </MapContainer>
      </div>

      {/* ---------------- SIDEBAR ---------------- */}
      <div
        style={{
          width: sidebarOpen ? 340 : 0,
          transition: "width 0.3s ease",
          overflow: "hidden",
          background: "#fafafa",
          borderLeft: "1px solid #ddd",
          padding: sidebarOpen ? 12 : 0,
        }}
      >
        {selected && (
          <div style={{ height: "100%", overflowY: "auto", padding: 8 }}>
            <button
              onClick={() => setSidebarOpen(false)}
              style={{
                float: "right",
                background: "#000",
                color: "#fff",
                borderRadius: 6,
                padding: "4px 10px",
                cursor: "pointer",
              }}
            >
              X
            </button>

            <h2>{selected.placeName}</h2>

            {/* Image */}
            <img
              src={selected.image || "/no-image.png"}
              alt=""
              loading="lazy"
              style={{
                width: "100%",
                aspectRatio: "16 / 9",
                height: "auto",
                objectFit: "cover",
                borderRadius: 8,
                marginBottom: 10,
              }}
              onError={(e) => {
                setSelected((prev) => {
                  if (!prev) return prev;
                  const queue = Array.isArray(prev.imageQueue) ? prev.imageQueue : [];
                  if (queue.length === 0) return { ...prev, image: "/no-image.png" };
                  const idx = Math.max(0, queue.indexOf(prev.image));
                  const nextIdx = idx + 1;
                  if (nextIdx < queue.length) {
                    return { ...prev, image: queue[nextIdx] };
                  }
                  return { ...prev, image: "/no-image.png" };
                });
              }}
            />

            <p><b>Address:</b><br />{selected.displayName}</p>
            <p>
              <b>Distance:</b>{" "}
              {selected.distanceFromUser
                ? `${selected.distanceFromUser} km`
                : "N/A"}
            </p>

            <b>Accessibility:</b>
            <ul>
              {Object.entries(selected.features || {}).map(([k, v]) => (
                <li key={k}>
                  {k}: <b>{v || "No"}</b>
                </li>
              ))}
            </ul>

            <div style={{ marginTop: 12 }}>
              <button
                onClick={() =>
                  isInCart(selected) ? removeFromCart(selected) : addToCart(selected)
                }
                style={{
                  padding: "8px 12px",
                  borderRadius: 8,
                  border: "2px solid #360146ff",
                  background: isInCart(selected) ? "#e6d6ff" : "#fff",
                  cursor: "pointer",
                  fontWeight: 600,
                  width: "100%",
                }}
              >
                {isInCart(selected) ? "Remove from Itinerary" : "Add to Itinerary"}
              </button>
            </div>
            {selected.location?.lat != null && selected.location?.lng != null && (
              <div style={{ marginTop: 12, marginBottom: 6 }}>
                <button
                  onClick={() => {
                    const origin = userLocation
                      ? `&origin=${userLocation.lat},${userLocation.lng}`
                      : "";
                    const url = `https://www.google.com/maps/dir/?api=1${origin}&destination=${selected.location.lat},${selected.location.lng}`;
                    window.open(url, "_blank", "noopener,noreferrer");
                  }}
                  style={{
                    padding: "8px 12px",
                    borderRadius: 8,
                    border: "2px solid #360146ff",
                    background: "#fff",
                    cursor: "pointer",
                    fontWeight: 600,
                    width: "100%",
                  }}
                >
                  Open in Google Maps
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
