import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { API_URL, apiGet, apiPost } from "./api";
import { executeChatCommand } from "./chatCommands";
import {
  addCartItem,
  fetchUserCart,
  subscribeToTravelDataChanges,
} from "./userTravelStore";

const FALLBACK_IMAGE = "/no-image.png";
const FAILED_CHAT_IMAGES = new Set();

function resolveImageSrc(image) {
  if (!image) return FALLBACK_IMAGE;
  if (typeof image === "string" && image.startsWith("http")) return image;
  if (typeof image === "string" && image.startsWith("/uploads/")) return `${API_URL}${image}`;
  return `${API_URL}/uploads/${image}`;
}

function getPlaceQueue(place) {
  const all = [place?.image, ...(place?.images || [])].filter(Boolean);
  return Array.from(new Set(all.map((img) => resolveImageSrc(img))));
}

function getChatPlaceImage(place) {
  const next = getPlaceQueue(place).find((url) => !FAILED_CHAT_IMAGES.has(url));
  return next || FALLBACK_IMAGE;
}

export default function QuickChatBox({ onClose }) {
  const navigate = useNavigate();
  const [language, setLanguage] = useState("en");
  const [destination, setDestination] = useState("");
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);
  const [coords, setCoords] = useState(null);
  const [messages, setMessages] = useState([]);
  const [approvedPlaces, setApprovedPlaces] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    if (!navigator.geolocation) return;
    navigator.geolocation.getCurrentPosition(
      (pos) => setCoords({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
      () => setCoords(null)
    );
  }, []);

  useEffect(() => {
    apiGet("/get-approved-places")
      .then((items) => setApprovedPlaces(Array.isArray(items) ? items : []))
      .catch(() => setApprovedPlaces([]));
  }, []);

  useEffect(() => {
    let alive = true;
    const loadCart = async () => {
      try {
        const items = await fetchUserCart();
        if (alive) setCart(items);
      } catch {
        if (alive) setCart([]);
      }
    };

    void loadCart();
    const unsubscribe = subscribeToTravelDataChanges(() => {
      void loadCart();
    }, { types: ["cart"] });

    return () => {
      alive = false;
      unsubscribe();
    };
  }, []);

  const matchPlacesInText = (text) => {
    const q = (text || "").toLowerCase();
    if (!q) return [];
    return approvedPlaces
      .filter((p) => {
        const name = (p.placeName || "").trim().toLowerCase();
        return name.length > 2 && q.includes(name);
      })
      .slice(0, 4);
  };

  const isInCart = (place) =>
    cart.some((c) => c._id === place._id || c.placeName === place.placeName);

  const addToCart = async (place) => {
    if (isInCart(place)) return;
    try {
      const next = await addCartItem({
        _id: place._id,
        placeName: place.placeName,
        image: place.image,
      });
      setCart(next);
    } catch (err) {
      alert(err.message || "Failed to add place.");
    }
  };

  const addToItinerary = async (place) => {
    await addToCart(place);
    navigate("/ai-itinerary");
  };

  async function handleSend() {
    if (!message.trim()) return;
    const userText = message.trim();
    const cmd = executeChatCommand(userText);

    if (cmd.handled) {
      const assistantText = cmd.message ? (cmd.message.startsWith("Pathease Assistant:") ? cmd.message : `Pathease Assistant: ${cmd.message}`) : "Pathease Assistant: Done.";
      setMessages((prev) => [
        ...prev,
        { role: "user", text: userText },
        { role: "assistant", text: assistantText, source: "local-command", llmError: "" },
      ]);
      setMessage("");
      return;
    }

    setLoading(true);
    setMessages((prev) => [...prev, { role: "user", text: userText }]);
    try {
      const data = await apiPost("/ai/guide-chat", {
        message: userText,
        destination,
        language,
        lat: coords?.lat,
        lng: coords?.lng,
        history: messages
          .filter((m) => m.role === "user" || m.role === "assistant")
          .map((m) => ({ role: m.role, text: m.text })),
      });
      const r = data.reply || data.error || "";
      const assistantText = r ? (r.startsWith("Pathease Assistant:") ? r : `Pathease Assistant: ${r}`) : "";
      setMessages((prev) => [
        ...prev,
        {
          role: "assistant",
          text: assistantText,
          source: data.source || "",
          llmError: data.llm_error || "",
        },
      ]);
    } catch (e) {
      const r = e?.message || "Failed to reach the guide service.";
      setMessages((prev) => [
        ...prev,
        { role: "error", text: r, source: "request-error", llmError: r },
      ]);
    } finally {
      setLoading(false);
      setMessage("");
    }
  }

  return (
    <div
      style={{
        width: "min(320px, 90vw)",
        height: "min(420px, 65vh)",
        background: "#ffffff",
        border: "1px solid #ddd",
        borderRadius: 12,
        boxShadow: "0 6px 18px rgba(0,0,0,0.15)",
        padding: 10,
        display: "flex",
        flexDirection: "column",
      }}
    >
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
        <div style={{ fontWeight: 700 }}>AI Guide Chat</div>
        <button
          onClick={onClose}
          aria-label="Close chat"
          style={{
            border: "1px solid #360146ff",
            background: "#fff",
            borderRadius: 6,
            cursor: "pointer",
            padding: "2px 6px",
          }}
        >
          X
        </button>
      </div>

      <select
        value={language}
        onChange={(e) => setLanguage(e.target.value)}
        style={{ width: "100%", padding: 6, borderRadius: 6, border: "1px solid #ccc", marginBottom: 6 }}
      >
        <option value="en">English</option>
        <option value="hi">Hindi</option>
        <option value="mr">Marathi</option>
      </select>

      <input
        value={destination}
        onChange={(e) => setDestination(e.target.value)}
        placeholder="Destination (optional)"
        style={{ width: "100%", padding: 6, borderRadius: 6, border: "1px solid #ccc", marginBottom: 6 }}
      />

      <div
        style={{
          flex: 1,
          minHeight: 0,
          overflowY: "auto",
          border: "1px solid #eee",
          borderRadius: 8,
          padding: 8,
          marginBottom: 8,
          background: "#fafafa",
        }}
      >
        {messages.map((m, i) => {
          const matchedPlaces =
            m.role === "assistant" ? matchPlacesInText(m.text) : [];
          return (
            <div
              key={i}
              style={{
                marginBottom: 10,
              }}
            >
              <div
                style={{
                  display: "flex",
                  gap: 8,
                  alignItems: "flex-start",
                }}
              >
                <div
                  style={{
                    width: 22,
                    height: 22,
                    borderRadius: 11,
                    background: m.role === "user" ? "#e6d6ff" : m.role === "assistant" ? "#d6f5e6" : "#ffd6d6",
                    textAlign: "center",
                    lineHeight: "22px",
                    fontSize: 12,
                    fontWeight: 700,
                    flexShrink: 0,
                  }}
                >
                  {m.role === "user" ? "U" : m.role === "assistant" ? "A" : "!"}
                </div>
                <div style={{ flex: 1, minWidth: 0, whiteSpace: "pre-wrap" }}>
                  {m.role === "assistant" && m.source && (
                    <div
                      style={{
                        marginBottom: 4,
                        padding: "4px 6px",
                        borderRadius: 6,
                        background: m.source === "llm" ? "#e7f7ee" : "#fff4e5",
                        border: `1px solid ${m.source === "llm" ? "#9ad4af" : "#f2c27b"}`,
                        fontSize: 11,
                      }}
                    >
                      Source: {m.source === "llm" ? "AI model" : m.source}
                      {m.llmError ? ` | LLM error: ${m.llmError}` : ""}
                    </div>
                  )}
                  {m.text}
                </div>
              </div>
              {matchedPlaces.length > 0 && (
                <div
                  style={{
                    marginTop: 8,
                    marginLeft: 30,
                    display: "grid",
                    gap: 6,
                  }}
                >
                  {matchedPlaces.map((p) => (
                    <div key={p._id || p.placeName} style={{ border: "1px solid #ddd", borderRadius: 8, padding: 6, background: "#fff" }}>
                      <img
                        src={getChatPlaceImage(p)}
                        alt={p.placeName}
                        style={{ width: "100%", height: 90, objectFit: "cover", borderRadius: 6 }}
                        onError={(e) => {
                          e.currentTarget.onerror = null;
                          FAILED_CHAT_IMAGES.add(e.currentTarget.src);
                          e.currentTarget.src = getChatPlaceImage(p);
                        }}
                      />
                      <div style={{ marginTop: 4, fontWeight: 600 }}>{p.placeName}</div>
                      <div style={{ marginTop: 6, display: "flex", gap: 6 }}>
                        <button onClick={() => addToItinerary(p)} style={{ flex: 1, padding: "4px 6px" }}>
                          Add to Itinerary
                        </button>
                        <button onClick={() => addToCart(p)} style={{ flex: 1, padding: "4px 6px" }}>
                          {isInCart(p) ? "Added" : "Add to Cart"}
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </div>

      <textarea
        rows={3}
        value={message}
        onChange={(e) => setMessage(e.target.value)}
        placeholder="Ask a local guide..."
        style={{ width: "100%", padding: 6, borderRadius: 6, border: "1px solid #ccc" }}
      />

      <button
        onClick={handleSend}
        style={{
          marginTop: 6,
          padding: "6px 10px",
          borderRadius: 8,
          border: "2px solid #360146ff",
          background: "#fff",
          cursor: "pointer",
          fontWeight: 600,
        }}
      >
        {loading ? "Sending..." : "Send"}
      </button>

    </div>
  );
}
